"""Export only six proposed Steam source files behind the existing panel auth."""
import base64,hashlib,json,os,pwd,socket,subprocess,tempfile,time,zipfile,fcntl
from pathlib import Path
PANEL_DATA = ''
PANEL_SHA = 'f5ba59e4f86b27d2907007ba58e400e648a8efe5bb5ce39fe0a945c7c1bba026'
PREVIOUS_SHA = '85c2583cdd23480008b1729512daa7af6b6692b1b307adbcefe417a97d33931f'
def digest(raw):
    return hashlib.sha256(raw).hexdigest()

def replace(target,raw,uid,gid,mode):
    target.parent.mkdir(parents=True,exist_ok=True)
    fd,temp=tempfile.mkstemp(prefix='.fh6-update-',dir=target.parent)
    try:
        with os.fdopen(fd,'wb') as stream:
            stream.write(raw);stream.flush();os.fsync(stream.fileno())
            os.fchown(stream.fileno(),uid,gid);os.fchmod(stream.fileno(),mode)
        os.replace(temp,target)
    finally:
        if Path(temp).exists():Path(temp).unlink()

def main():
    if os.geteuid()!=0 or socket.gethostname()!='fh6-collector':raise RuntimeError('Run only in CT109')
    store=Path('/var/lib/fh6');root=Path('/opt/fh6/repo')
    work=store/'task-workspaces/69b691a5b3af41b8afcb10c2da93f2c8'
    names=['automation/server/steam_publish.py','automation/server/test_steam_publish.py',
           'automation/server/fh6-steam.service','automation/server/fh6-steam.timer',
           'docs/STEAM_AUTOPUBLISH.md','automation/server/phone_ui.py']
    entries={}
    for name in names:
        file=work/name
        if file.is_symlink() or not file.resolve().is_relative_to(work.resolve()) or not file.is_file():raise RuntimeError('Missing/unsafe proposal file: '+name)
        entries[name]=file.read_bytes()
    if sum(map(len,entries.values()))>1_000_000:raise RuntimeError('Proposal too large')
    owner=pwd.getpwnam('fh6');target=root/'automation/server/phone_ui.py'
    with (store/'runner.lock').open('a+b') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        if target.is_symlink():raise RuntimeError('Unexpected panel symlink')
        before=target.read_bytes()
        if digest(before) not in {PREVIOUS_SHA,PANEL_SHA}:raise RuntimeError('Unknown panel version; no files changed')
        raw=base64.b64decode(PANEL_DATA,validate=True)
        if digest(raw)!=PANEL_SHA:raise RuntimeError('Payload mismatch')
        compile(raw,'phone_ui.py','exec')
        backup=store/'repairs'/('review-download-'+str(time.time_ns()));backup.mkdir(parents=True,mode=0o700)
        (backup/'phone_ui.py').write_bytes(before)
        archive=store/'steam-review.zip';fd,name=tempfile.mkstemp(dir=store,prefix='.steam-review-');os.close(fd)
        try:
            with zipfile.ZipFile(name,'w',compression=zipfile.ZIP_DEFLATED) as zipped:
                for path,content in entries.items():zipped.writestr(path,content)
                zipped.writestr('MANIFEST.json',json.dumps({'workspace':work.name,'files':{p:digest(c) for p,c in entries.items()}},indent=2))
            with zipfile.ZipFile(name) as zipped:
                if zipped.testzip():raise RuntimeError('Bad archive')
            os.chown(name,owner.pw_uid,owner.pw_gid);os.chmod(name,0o640);os.replace(name,archive)
            stat=target.stat();replace(target,raw,stat.st_uid,stat.st_gid,stat.st_mode&0o7777)
            try:
                subprocess.run(['systemctl','restart','fh6-phone.service'],check=True,timeout=30)
                subprocess.run(['systemctl','is-active','--quiet','fh6-phone.service'],check=True,timeout=30)
            except BaseException:
                replace(target,before,stat.st_uid,stat.st_gid,stat.st_mode&0o7777)
                subprocess.run(['systemctl','restart','fh6-phone.service'],timeout=30);raise
        finally:Path(name).unlink(missing_ok=True)
    print('STEAM_REVIEW_EXPORT_READY files=6; no Steam installation or publication')
    print('BACKUP='+str(backup))

if __name__=='__main__':main()
